import{_ as a,o as e,c as i,a3 as t}from"./chunks/framework.B7pF4b99.js";const k=JSON.parse('{"title":"01 · 開始使用","description":"選擇 Windows 免安裝版或 WSL 原始碼，啟動 WUWAOS 並執行第一條 shell 指令。","frontmatter":{"description":"選擇 Windows 免安裝版或 WSL 原始碼，啟動 WUWAOS 並執行第一條 shell 指令。"},"headers":[],"relativePath":"topics/getting-started.md","filePath":"topics/getting-started.md","lastUpdated":1794402144000}'),n={name:"topics/getting-started.md"};function l(o,s,r,d,p,h){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="_01-·-開始使用" tabindex="-1">01 · 開始使用 <a class="header-anchor" href="#_01-·-開始使用" aria-label="Permalink to &quot;01 · 開始使用&quot;">​</a></h1><p>從 Windows 啟動 WUWAOS。選一種方式，看到 <code>wuwaos/&gt;</code> 後就能在系統裡輸入第一條指令。</p><nav class="start-routes" aria-label="選擇啟動方式"><a href="#windows-portable"><strong>Windows 免安裝版</strong><span>下載 ZIP，直接體驗 CLI 或圖形桌面。</span></a><a href="#wsl-source"><strong>從原始碼啟動（WSL）</strong><span>用 Ubuntu 建置，從 WUFS 磁碟開機。</span></a></nav><h2 id="建置與啟動" tabindex="-1">建置與啟動 <a class="header-anchor" href="#建置與啟動" aria-label="Permalink to &quot;建置與啟動&quot;">​</a></h2><h3 id="windows-portable" tabindex="-1">Windows 免安裝版 <a class="header-anchor" href="#windows-portable" aria-label="Permalink to &quot;Windows 免安裝版 {#windows-portable}&quot;">​</a></h3><p>下載 <a href="https://github.com/johnson931128/WUWAOS/releases/tag/portable-windows-v1" target="_blank" rel="noreferrer">Windows portable v1 Release</a> 的完整 ZIP 並解壓。下載與校驗步驟見 <a href="./../portable-windows.html">Windows portable 指南</a>。</p><p><strong>在 PowerShell 輸入</strong>，先切換到解壓後的專案根目錄。</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>腳本會準備建置環境、編譯並開啟 QEMU。看到 <strong><code>wuwaos/&gt;</code></strong> 就可以往下執行 shell 指令。想直接開啟圖形桌面，可用 <strong>PowerShell</strong> 執行 <code>.\\Start-WUWAOS.cmd gui</code>。</p><h3 id="wsl-source" tabindex="-1">從原始碼啟動（WSL） <a class="header-anchor" href="#wsl-source" aria-label="Permalink to &quot;從原始碼啟動（WSL） {#wsl-source}&quot;">​</a></h3><p>WSL Ubuntu 需備有 Clang、LLD、llvm-objcopy、Make、Python 3、QEMU RISC-V 與 OpenSBI。請將以下路徑換成你的專案目錄。</p><p><strong>在 PowerShell 輸入</strong></p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd C:\\programing\\WUWAOS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> make run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disk</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>指令在 WSL 交叉編譯並準備 WUFS 映像，接著啟動 QEMU。看到 <strong><code>wuwaos/&gt;</code></strong> 就表示 WUWAOS shell 已就緒。</p><h2 id="進入系統後" tabindex="-1">進入系統後 <a class="header-anchor" href="#進入系統後" aria-label="Permalink to &quot;進入系統後&quot;">​</a></h2><ol class="start-flow" aria-label="從主機啟動到 WUWAOS shell"><li><strong>Windows 主機</strong><span>在 PowerShell 啟動</span></li><li><strong>QEMU virt</strong><span>模擬 RISC-V 硬體</span></li><li><strong>WUWAOS shell</strong><span>看到提示字元後輸入</span></li></ol><p>看到提示字元後，在同一個視窗輸入 <code>help</code> 並按 Enter。這時，指令已經交給 QEMU 裡的 WUWAOS shell。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wuwaos/&gt; help</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>help</code> 會列出可用命令。接著可用 <code>ps</code> 查看行程、<code>vmstat</code> 查看分頁統計、<code>ls /</code> 查看根目錄。用 <code>fan /home/user/note.txt</code> 可以進入編輯器，操作見 <a href="./applications.html">使用者程式</a>。</p><p><strong>離開 CLI 的 QEMU</strong>，按 Ctrl+A，放開後按 X。Shell 裡的 <code>exit</code> 會結束目前 shell，QEMU 仍會繼續執行。</p><h2 id="進階啟動與磁碟" tabindex="-1">進階啟動與磁碟 <a class="header-anchor" href="#進階啟動與磁碟" aria-label="Permalink to &quot;進階啟動與磁碟&quot;">​</a></h2><h3 id="磁碟開機與直接開機" tabindex="-1">磁碟開機與直接開機 <a class="header-anchor" href="#磁碟開機與直接開機" aria-label="Permalink to &quot;磁碟開機與直接開機&quot;">​</a></h3><p><code>make run-disk</code> 將核心安裝到 <code>build/wuwaos-cli.img</code>。QEMU 啟動 OpenSBI 後，flash 載入器會從磁碟讀取 <code>/boot/kernel.elf</code>。這條路徑使用一顆 WUFS0002 磁碟，停用 swap，並要求 journal 無待重播紀錄。<code>make clean</code> 保留磁碟與其中的檔案。</p><p>若需要由 QEMU 直接載入核心並附加 swap 磁碟，在 <strong>PowerShell</strong> 執行 <code>wsl -d Ubuntu -- make run</code>。此路徑使用 <code>build/wuwaos.img</code> 與 <code>build/wuwaos-swap.img</code>。若 journal 有待重播紀錄，請走會跳過主機映像更新的<a href="./../SPEC-32-wufs-redo-journal.html#新磁碟與-pending-recovery-操作">復原流程</a>。</p><h3 id="搭配-portable-工具環境" tabindex="-1">搭配 portable 工具環境 <a class="header-anchor" href="#搭配-portable-工具環境" aria-label="Permalink to &quot;搭配 portable 工具環境&quot;">​</a></h3><p>在 <strong>PowerShell</strong> 執行 <code>.\\Start-WUWAOS.cmd build</code> 可以只編譯並準備磁碟映像。需要直接使用 Makefile 時，執行 <code>.\\Start-WUWAOS.cmd shell</code> 進入隨附的 <strong>Bash</strong>，再執行 <code>make</code>、<code>make run</code> 或 <code>make run-gui GUI_DISPLAY=gtk</code>。</p><p>若搭配目前原始碼，也可在該 <strong>Bash</strong> 執行 <code>make run-disk</code>。原始 portable v1 ZIP 內含該版本的直接開機流程，<code>run-disk</code> 需要目前原始碼。</p><h3 id="磁碟保護與驗證" tabindex="-1">磁碟保護與驗證 <a class="header-anchor" href="#磁碟保護與驗證" aria-label="Permalink to &quot;磁碟保護與驗證&quot;">​</a></h3><p>目前原始碼在核心與主機映像工具都會保護非空白磁碟。若 magic 不符，只有確認全部資料為零才允許初始化。要核對空白、損毀與尾端資料的處理，請從目前原始碼的專案根目錄，在 <strong>PowerShell</strong> 使用既有入口。</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blank</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> damaged</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tail</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>每次執行都會建立獨立測試磁碟。依畫面提示退出 QEMU 後，工具會檢查前後雜湊。這些入口與保護修正於 portable v1 之後加入。預期訊息、既有結果與驗證範圍見 <a href="./../SPEC-31-filesystem-initialization-guard.html">Spec 31</a>。</p><h2 id="對應程式碼" tabindex="-1">對應程式碼 <a class="header-anchor" href="#對應程式碼" aria-label="Permalink to &quot;對應程式碼&quot;">​</a></h2><p><code>Makefile</code> 負責交叉編譯、連結與 QEMU 參數。<code>tools/make_disk.py</code> 維護 WUFS 映像，<code>tools/make_swap.py</code> 建立 swap 映像。這些工具都在主機執行。</p><p>觀念參考見 <code>notes/ch1 Introduction.md</code> 與 <code>notes/ch2 Operating-System Structures.md</code>。既有 OS 操作結果見<a href="./../history.html">規格紀錄</a>，文件站的啟動方式見<a href="./writing.html">維護文件網站</a>。</p><p><strong>接著讀 <a href="./boot.html">〈開機流程〉</a></strong>，看 OpenSBI、flash 載入器和 WUWAOS 核心如何交接。</p>`,35)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
